// SPDX-License-Identifier: MIT
pragma solidity 0.8.0;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/BybetTokenERC20.sol";

contract BybetTokenTest is Test {
    BybetTokenERC20 token;
    address owner = address(0x1);
    address user1 = address(0x2);
    address user2 = address(0x3);
    address mockPair1 = address(0x4);
    address mockPair2 = address(0x5);

    function setUp() public {
        vm.mockCall(
            address(0x10ED43C718714eb63d5aA57B78B54704E256024E),
            abi.encodeWithSignature("factory()"),
            abi.encode(address(0x6))
        );

        vm.mockCall(
            address(0x10ED43C718714eb63d5aA57B78B54704E256024E),
            abi.encodeWithSignature("WETH()"),
            abi.encode(address(0x7))
        );

        vm.mockCall(
            address(0x6),
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(address(0x8))
        );

        vm.startPrank(owner);
        token = new BybetTokenERC20();
        vm.stopPrank();
    }

    function testWhitelistUniqueness() public {
        vm.startPrank(owner);

        // Whitelist user1 initially - should succeed
        token.setWhitelist(user1);
        assertTrue(token.checkFeeExempt(user1), "User1 should be whitelisted");

        // Whitelist the same user again - should not revert or break
        token.setWhitelist(user1);
        assertTrue(token.checkFeeExempt(user1), "User1 should still be whitelisted");

        // Check other user is not whitelisted
        assertFalse(token.checkFeeExempt(user2), "User2 should not be whitelisted");

        vm.stopPrank();
    }

    function testAMMPairUniqueness() public {
        vm.startPrank(owner);

        // Set pair1 as AMM pair
        token.setAutomatedMarketMakerPair(mockPair1, true);
        assertTrue(token.automatedMarketMakerPairs(mockPair1), "mockPair1 should be set");

        // Set the same pair again - should not break
        token.setAutomatedMarketMakerPair(mockPair1, true);
        assertTrue(token.automatedMarketMakerPairs(mockPair1), "mockPair1 should still be set");

        // Set pair2 as AMM pair
        token.setAutomatedMarketMakerPair(mockPair2, true);
        assertTrue(token.automatedMarketMakerPairs(mockPair2), "mockPair2 should be set");

        // Remove pair1
        token.setAutomatedMarketMakerPair(mockPair1, false);
        assertFalse(token.automatedMarketMakerPairs(mockPair1), "mockPair1 should be unset");

        // Remove pair1 again - should not break
        token.setAutomatedMarketMakerPair(mockPair1, false);
        assertFalse(token.automatedMarketMakerPairs(mockPair1), "mockPair1 should still be unset");

        vm.stopPrank();
    }
}
